import { Suspense, lazy, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { Diagnostic, MatchInfo, OrderInput, SavedOrder } from './domain/types';
import { createMatchInfo } from './domain/types';
import {
  createVersion,
  deriveOrderState,
  latestVersion,
  orderFingerprint,
} from './domain/orders/lifecycle';
import { seasonCommitStatus } from './domain/orders/seasonLedger';
import { orderOwnershipIssue } from './domain/orders/ownership';
import { validateHardConstraints } from './optimizer/constraints/validate';
import { formatStructureIssues } from './domain/games/format';
import { createId } from './utils/id';
import { syncParticipants } from './domain/orders/participants';
import { guestsOf } from './domain/players/newPlayer';
import {
  autoValuesOf,
  syncMatchWithTeam,
  type AutoMatchValues,
} from './domain/orders/matchInfo';
import { createRunner, type OrderRunner } from './optimizer/runner';
import { useAppStore } from './state/appStore';
import {
  createUndoable,
  undoableReducer,
  type UndoableAction,
  type UndoableState,
} from './state/orderSession';
import { BACK_TARGETS, PAGE_TITLES, TAB_FOR_PAGE, TABS, type Page } from './navigation';
import { onUpdateAvailable } from './pwa';
import { ConfirmDialog, EmptyState, STATE_META, StatusBadge, useToast } from './components/ui';
import { Icon } from './components/icons';
import { Breadcrumbs, MenuButton, MenuDrawer } from './components/AppNav';
import { KineticText } from './components/motion';
import { ChangelogSheet } from './components/ChangelogSheet';
import { HomePage, type WorkingOrderSummary } from './pages/HomePage';
import { PlayersPage } from './pages/PlayersPage';
import { PairsPage } from './pages/PairsPage';
import { FormatsPage } from './pages/FormatsPage';
import { SetupPage, type SetupDraft } from './pages/SetupPage';
import { ResultPage } from './pages/ResultPage';
import { HistoryPage } from './pages/HistoryPage';
import { SettingsPage } from './pages/SettingsPage';
import { MorePage } from './pages/MorePage';
import { WelcomePage } from './pages/WelcomePage';
import { ViewerHome, ViewerOrder } from './pages/ViewerPages';
import type { NextMatchOrder } from './domain/n01/nextMatch';
import { readWatchLink, replaceWatchLink, useWatchLink } from './features/matches/watchLink';

// Loaded only when the analytics screen is opened: it adds nothing to start-up and makes no
// network request until then.
const AnalyticsEntry = lazy(() => import('./features/analytics/ui/AnalyticsEntry'));
// MATCH RESULTS / LIVE MATCH: loaded only when opened, like analytics.
const MatchesEntry = lazy(() => import('./features/matches/ui/MatchesEntry'));

/**
 * Application shell.
 *
 * Owns navigation, the order session (with its undo history) and the optimizer runner.
 * The runner lives here rather than in a page so that generation survives navigating
 * between SETUP and RESULT.
 *
 * `record` is the persisted order the working copy belongs to. It is what makes a
 * re-generation from SETUP a *revision* of that order (UPDATED → v2) rather than a new
 * draft: it is only cleared when the captain explicitly starts a new order.
 */
export function App(): React.JSX.Element {
  const store = useAppStore();
  const toast = useToast();
  // A link to a card or a game (new tab, reload) opens 観戦 straight away.
  const [page, setPage] = useState<Page>(() => (readWatchLink() ? 'watch' : 'home'));
  const watchLink = useWatchLink();
  const [session, setSession] = useState<UndoableState | null>(null);
  const [diagnostics, setDiagnostics] = useState<Diagnostic[]>([]);
  /** The input of the attempt the diagnostics describe (it never replaces the order's own). */
  const [diagnosticInput, setDiagnosticInput] = useState<OrderInput | null>(null);
  const [generating, setGenerating] = useState(false);
  const runnerRef = useRef<OrderRunner | null>(null);
  /**
   * Generation token. Every request takes the next number; anything that makes a running
   * request unwanted (another team, a new order, opening a saved order, discarding, leaving
   * the app) bumps it. An answer whose number is no longer current — success, "no
   * solution" or failure alike — is dropped without touching the screen, the
   * notifications or the spinner, so it can never be shown or saved as this team's order.
   */
  const generationRef = useRef(0);

  /** Retires the running request (if any): its answer will be ignored. */
  const invalidateGeneration = useCallback(() => {
    generationRef.current += 1;
    setGenerating(false);
  }, []);

  const [draft, setDraft] = useState<SetupDraft | null>(null);
  const [match, setMatch] = useState<MatchInfo>(() => createMatchInfo());
  /** The persisted order record, once the captain has saved or finalized it. */
  const [record, setRecord] = useState<SavedOrder | null>(null);
  const [applyUpdate, setApplyUpdate] = useState<(() => void) | null>(null);
  /** What to do once the captain agrees to discard unsaved work (null = no dialog). */
  const [confirmDiscard, setConfirmDiscard] = useState<(() => void) | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  /** A format to open in the editor when FORMAT opens (the first-run "自分の構成を作る"). */
  const [formatToEdit, setFormatToEdit] = useState<string | null>(null);
  const [showChangelog, setShowChangelog] = useState(false);

  // A new build is never applied automatically — the captain decides when.
  useEffect(() => onUpdateAvailable((apply) => setApplyUpdate(() => apply)), []);

  useEffect(() => {
    runnerRef.current = createRunner();
    return () => {
      // Nothing that answers after the app is gone may write anything.
      generationRef.current += 1;
      runnerRef.current?.dispose();
      runnerRef.current = null;
    };
  }, []);

  const hasTeams = store.teams.length > 0;
  // Viewer without a team who chose 「チームを登録」.
  const [registering, setRegistering] = useState(false);

  // The working order belongs to the team it was made for. Switching (or deleting) the
  // active team detaches it: otherwise SETUP re-syncs to the new team's roster while
  // `record` still points at the old team's order, and re-generating would write one
  // team's line-up into the other team's history.
  const workingTeam = useRef<string | null>(null);
  useEffect(() => {
    if (!store.ready) return;
    const previous = workingTeam.current;
    workingTeam.current = store.activeTeamId;
    if (previous !== null && previous !== store.activeTeamId) {
      // A line-up still being computed for the old team must not arrive in this one.
      invalidateGeneration();
      setSession(null);
      setRecord(null);
      setDiagnostics([]);
      // One team's one-order helpers are nobody's in the other team.
      setDraft((current) => (current && current.guests.length > 0 ? clearGuests(current) : current));
    }
  }, [store.ready, store.activeTeamId, invalidateGeneration]);

  // Every screen opens at its top; keeping the previous screen's scroll offset made HOME
  // open mid-page with the main action scrolled out of view.
  useEffect(() => {
    window.scrollTo(0, 0);
    if (page !== 'formats') setFormatToEdit(null);
    // The address names a card only while 観戦 is shown.
    if (page !== 'watch' && page !== 'matches' && page !== 'live' && readWatchLink()) replaceWatchLink(null);
  }, [page]);

  // A link arriving while another screen is open (pasted into the address bar, back / forward).
  const linkKey = watchLink ? JSON.stringify(watchLink) : null;
  useEffect(() => {
    if (linkKey) setPage((current) => (current === 'watch' || current === 'matches' || current === 'live' ? current : 'watch'));
  }, [linkKey]);

  // "Delete everything" returns to the first-run state, so nothing from the old data may
  // linger in the working copy.
  useEffect(() => {
    if (!store.ready || hasTeams) return;
    invalidateGeneration();
    setSession(null);
    setRecord(null);
    setDiagnostics([]);
    setDraft(null);
    setPage('home');
  }, [store.ready, hasTeams, invalidateGeneration]);

  // Watching without a team opens on 観戦 (on choosing a league, and again after a reload).
  // Declared after the reset above, which sends a teamless app to ホーム, so this one wins.
  const viewing = store.ready && !hasTeams && (Boolean(store.settings.watch) || watchLink !== null);
  const wasViewing = useRef(false);
  useEffect(() => {
    if (viewing && !wasViewing.current) setPage('watch');
    wasViewing.current = viewing;
  }, [viewing]);

  // Keep the setup draft in step with the roster and the saved settings.
  useEffect(() => {
    if (!store.ready || !hasTeams) return;
    setDraft((current) => {
      const formatId =
        current && store.teamFormats.some((format) => format.id === current.formatId)
          ? current.formatId
          : (store.teamFormats[0]?.id ?? '');
      // The order's own guests are not on the roster: they are kept explicitly, or a roster
      // sync would drop their rows (and the conditions set on them).
      const guests = current?.guests ?? [];
      const participants = syncParticipants(current?.participants ?? [], store.teamPlayers, guests);
      return {
        formatId,
        participants,
        guests,
        preset: current?.preset ?? store.settings.lastPreset,
        settings: current?.settings ?? store.settings.optimizer,
      };
    });
  }, [store.ready, hasTeams, store.teamPlayers, store.teamFormats, store.settings]);

  /**
   * Keeps the match header in step with the active team (see `syncMatchWithTeam`).
   *
   * The previous automatic values are read into a local before the ref is updated: the
   * state updater runs after this effect body, so reading the ref from inside it would
   * always see the new values and never recognise an untouched field.
   */
  const autoMatch = useRef<AutoMatchValues>({ teamName: '', leagueName: '' });
  useEffect(() => {
    if (!store.ready) return;
    const previous = autoMatch.current;
    autoMatch.current = autoValuesOf(store.activeTeam);
    setMatch((current) => syncMatchWithTeam(current, previous, store.activeTeam));
  }, [store.ready, store.activeTeam]);

  const dispatch = useCallback((action: UndoableAction) => {
    setSession((current) => (current ? undoableReducer(current, action) : current));
  }, []);

  const run = useCallback(
    async (input: OrderInput, options?: { candidateCount?: number }) => {
      const runner = runnerRef.current;
      if (!runner) return;
      // A game that contradicts itself (two player-count kinds, a two-player Singles) is
      // never generated: the format is corrected first (FORMAT screen).
      const structure = formatStructureIssues(input.games);
      if (structure.length > 0) {
        toast.show(`生成できません: ${structure[0].message} フォーマット画面で修正してください。`, 'error');
        return;
      }
      generationRef.current += 1;
      const token = generationRef.current;
      // Still wanted: no newer request, no reset since, and still the active team's.
      const live = (): boolean => token === generationRef.current && input.teamId === workingTeam.current;
      setGenerating(true);
      setDiagnostics([]);
      try {
        const result = await runner.generate(input, options);
        if (!live()) return;
        if (result.ok) {
          setSession((current) => {
            const base = current && current.present.current ? current : createUndoable(input);
            const withInput = undoableReducer(base, { type: 'setInput', input });
            // An underdog plan travels with the result but is only offered, never shown first.
            return undoableReducer(withInput, { type: 'generated', candidates: result.candidates, underdog: result.underdog ?? null });
          });
          setDiagnostics([]);
          setPage('result');
        } else {
          setSession((current) => {
            // Keep the previous order visible so the captain does not lose their work;
            // the diagnostics explain why the new attempt failed. Its input stays too:
            // pairing the old line-up with the failed attempt's conditions would let a
            // later save store a combination that was never generated together.
            if (current?.present.current) return current;
            return undoableReducer(current ?? createUndoable(input), { type: 'setInput', input });
          });
          setDiagnostics(result.diagnostics);
          setDiagnosticInput(input);
          setPage('result');
          toast.show('条件を満たすオーダーがありません。理由を表示します。', 'error');
        }
      } catch (error) {
        if (!live()) return;
        toast.show(`生成に失敗しました: ${(error as Error).message}`, 'error');
      } finally {
        // A retired request leaves the spinner to the request that replaced it.
        if (token === generationRef.current) setGenerating(false);
      }
    },
    [toast],
  );

  /**
   * Generation from SETUP.
   *
   * When the working copy belongs to a saved order (`record`), this is a revision of that
   * order: the record is kept, so the lifecycle compares the new line-up with the last
   * finalized version and shows UPDATED → "再確定 v2". A new order is started explicitly
   * (`startNewOrder`), never as a side effect of pressing generate.
   */
  const handleGenerate = useCallback(
    (input: OrderInput) => {
      store.updateSettings({
        lastPreset: input.preset,
        optimizer: input.settings,
      });
      // Never revise another team's order with this team's input.
      if (record && record.teamId !== input.teamId) setRecord(null);
      void run(input);
    },
    [run, store, record],
  );

  /** Drops the working copy so the next generation is a brand-new order. */
  const resetWorkingOrder = useCallback(() => {
    invalidateGeneration();
    setSession(null);
    setRecord(null);
    setDiagnostics([]);
  }, [invalidateGeneration]);

  /**
   * True when the working copy holds anything not yet in storage: an order never saved,
   * or a saved order edited or re-generated since. `persist` stores the session's own
   * input and solution objects, so identity is exactly "unchanged since the last save".
   * The match header is compared by value on the fields the fingerprint reads: it is
   * rebuilt by the team-sync effect, so its identity says nothing. Every record in the
   * session has one (`persist` writes it; `openSavedOrder` fills it in for old records).
   */
  const unsaved =
    !!session?.present.current &&
    (!record ||
      record.solution !== session.present.current ||
      record.input !== session.present.input ||
      !sameMatch(record.match ?? match, match));

  const startNewOrder = useCallback(
    (force = false) => {
      const start = (): void => {
        resetWorkingOrder();
        // A guest plays one order: the next one starts without them.
        setDraft((current) => (current && current.guests.length > 0 ? clearGuests(current) : current));
        setPage('setup');
      };
      // Work that only exists in this session is never dropped without asking.
      if (!force && unsaved) {
        setConfirmDiscard(() => start);
        return;
      }
      start();
    },
    [unsaved, resetWorkingOrder],
  );

  /**
   * Re-optimisation (spec §17). `keepGameId === null` keeps the current locks as they
   * are; otherwise every other game is pinned first so only the named game can change.
   */
  const handleReoptimise = useCallback(
    (keepGameId: string | null) => {
      setSession((current) => {
        if (!current?.present.current) return current;
        const next =
          keepGameId === null
            ? current
            : undoableReducer(current, { type: 'lockAllExcept', gameId: keepGameId });
        void run(next.present.input, { candidateCount: 1 });
        return next;
      });
    },
    [run],
  );

  /**
   * 「次戦のオーダーを作る」 (Phase 5): a new order for the next match, set up exactly as
   * SETUP would set it up — the managed format, today's attendance, the next opponent in
   * the match header — so the captain can still go back to SETUP and adjust anything.
   */
  const generateNextMatch = useCallback(
    (order: NextMatchOrder) => {
      const start = (): void => {
        resetWorkingOrder();
        setMatch(order.match);
        setDraft({
          formatId: order.input.formatId,
          participants: order.input.participants,
          guests: guestsOf(order.input.players),
          preset: order.input.preset,
          settings: order.input.settings,
        });
        // Caps the league does not state are asked on SETUP before anything is generated.
        if (order.pendingRules.length > 0) {
          setPage('setup');
          toast.show('出場回数の規則が未確認です。確認してから生成してください。');
          return;
        }
        handleGenerate(order.input);
      };
      if (unsaved) {
        setConfirmDiscard(() => start);
        return;
      }
      start();
    },
    [unsaved, resetWorkingOrder, handleGenerate],
  );

  const handleRegenerate = useCallback(() => {
    if (!session?.present.input) return;
    void run(session.present.input);
  }, [run, session]);

  const openSavedOrder = useCallback(
    (order: SavedOrder) => {
      // A generation still running belongs to whatever was open before.
      invalidateGeneration();
      const restored = undoableReducer(createUndoable(order.input), {
        type: 'generated',
        candidates: [order.solution],
      });
      setSession(restored);
      // A saved order carries the match it was played for, so re-sharing it later
      // reproduces the same header, and its versions so the lifecycle resumes correctly.
      // Orders saved before the match header existed have none: the header in use when
      // they are opened becomes their baseline, so later edits still count as unsaved.
      const baseline = order.match ?? match;
      setMatch(baseline);
      setRecord(order.match ? order : { ...order, match: baseline });
      // SETUP edits this order from now on: restore the conditions it was generated
      // with, so going back and re-generating revises *this* order's line-up.
      setDraft({
        formatId: store.teamFormats.some((format) => format.id === order.input.formatId)
          ? order.input.formatId
          : (store.teamFormats[0]?.id ?? ''),
        // The order's own guests come back with it, from its snapshot of players.
        participants: syncParticipants(order.input.participants, store.teamPlayers, guestsOf(order.input.players)),
        guests: guestsOf(order.input.players),
        preset: order.input.preset,
        settings: order.input.settings,
      });
      setDiagnostics([]);
      setPage('result');
      toast.show('履歴から読み込みました', 'ok');
    },
    [toast, store.teamFormats, store.teamPlayers, match, invalidateGeneration],
  );

  const games = useMemo(() => {
    if (session?.present.input.games.length) return session.present.input.games;
    const format = store.teamFormats.find((entry) => entry.id === draft?.formatId);
    return format?.games ?? [];
  }, [session, store.teamFormats, draft]);

  const solution = session?.present.current ?? null;

  /**
   * Lifecycle state (追加要件 §2, §8).
   *
   * Derived from the finalized versions and a fingerprint of the working copy, so it can
   * never go stale: an edit that changes what the team would see flips FINALIZED to
   * UPDATED by itself, and merely opening the share screen cannot change it.
   */
  const currentFingerprint = useMemo(
    () => (solution ? orderFingerprint(games, solution.assignments, match) : null),
    [solution, games, match],
  );

  const lifecycle = useMemo(
    () => deriveOrderState(record?.versions ?? [], currentFingerprint),
    [record, currentFingerprint],
  );

  const seasonStatus = useMemo(() => {
    if (!record) return 'none' as const;
    const commit = store.seasonCommitFor(record.id);
    return seasonCommitStatus(commit, latestVersion(record.versions)?.version ?? null);
  }, [record, store]);

  /**
   * Creates or updates the persisted record for the current working order.
   *
   * The record's team is the team the order was generated for (`input.teamId`), and the
   * write is refused when that is not the active team or not the team of the record being
   * updated (`orderOwnershipIssue`): nothing is written rather than something repaired.
   */
  const persist = useCallback(
    (mutate: (base: SavedOrder) => SavedOrder): { ok: true; order: SavedOrder } | { ok: false; message: string | null } => {
      if (!session?.present.current) return { ok: false, message: null };
      const issue = orderOwnershipIssue({ activeTeamId: store.activeTeamId, input: session.present.input, record });
      if (issue) return { ok: false, message: issue.message };
      const now = Date.now();
      const base: SavedOrder =
        record ??
        {
          id: createId('ord'),
          teamId: session.present.input.teamId,
          title: `${new Date(now).toLocaleDateString('ja-JP')} ${session.present.current.meta.label}`,
          createdAt: now,
          updatedAt: now,
          input: session.present.input,
          solution: session.present.current,
          match,
          versions: [],
          seasonApplied: false,
        };

      const next = mutate({
        ...base,
        updatedAt: now,
        input: session.present.input,
        solution: session.present.current,
        match,
      });
      setRecord(next);
      store.saveOrder(next);
      return { ok: true, order: next };
    },
    [record, session, store, match],
  );

  const handleSaveDraft = useCallback(() => {
    const saved = persist((base) => base);
    if (saved.ok) toast.show('履歴に保存しました', 'ok');
    else toast.show(saved.message ?? '保存できませんでした', 'error');
  }, [persist, toast]);

  /**
   * Finalization (追加要件 §3, §4).
   *
   * Re-validates every hard constraint before freezing a version: a line-up that breaks
   * one must never be handed to the team as confirmed.
   */
  const handleFinalize = useCallback(() => {
    if (!session?.present.current) return;
    const violations = validateHardConstraints(session.present.input, session.present.current.assignments);
    if (violations.length > 0) {
      toast.show(`確定できません: ${violations[0].message}`, 'error');
      return;
    }
    // An order made with a self-contradicting format stays viewable, but is not handed to
    // the team as confirmed.
    const structure = formatStructureIssues(session.present.input.games);
    if (structure.length > 0) {
      toast.show(`確定できません: ${structure[0].message} フォーマットを修正して作り直してください。`, 'error');
      return;
    }
    if (lifecycle === 'FINALIZED') {
      toast.show('すでに確定済みです (内容に変更はありません)', 'ok');
      return;
    }

    const saved = persist((base) => ({
      ...base,
      versions: [
        ...base.versions,
        createVersion(session.present.input, session.present.current!, match, base.versions, Date.now()),
      ],
    }));
    if (!saved.ok) {
      toast.show(saved.message ? `確定できません: ${saved.message}` : '確定できませんでした', 'error');
      return;
    }
    const version = latestVersion(saved.order.versions)!;
    toast.show(`v${version.version} として確定しました`, 'ok');
  }, [session, lifecycle, persist, match, toast]);

  const handleCommitSeason = useCallback(async () => {
    if (!record) return;
    const version = latestVersion(record.versions);
    if (!version) return;
    // Season totals belong to the order's own team only.
    const issue = orderOwnershipIssue({ activeTeamId: store.activeTeamId, input: record.input, record });
    if (issue) {
      toast.show(`シーズン累計へ反映できません: ${issue.message}`, 'error');
      return;
    }
    const result = await store.commitSeason(record, version);
    toast.show(result.message, result.ok ? 'ok' : 'error');
    if (result.clamped.length > 0) {
      toast.show(`${result.clamped.length} 名の累計が 0 未満になるため 0 に丸めました`, 'error');
    }
  }, [record, store, toast]);

  const handleWithdrawSeason = useCallback(async () => {
    if (!record) return;
    const result = await store.withdrawSeason(record.id);
    toast.show(result.message, result.ok ? 'ok' : 'error');
  }, [record, store, toast]);

  if (!store.ready) {
    return (
      <div className="app">
        <main className="app-main">
          <div className="loading">
            <span className="spinner" aria-hidden="true" />
            <p>読み込み中…</p>
          </div>
        </main>
      </div>
    );
  }

  // No team, but a league chosen to watch: the same five tabs as with a team, in the same places.
  // Watching, settings and the change log work as they are; ORDER and the team screens say a
  // team is needed and offer to register one (or the sample) right there.
  if (!hasTeams && (store.settings.watch || watchLink) && !registering) {
    const register = (): void => setRegistering(true);
    const viewerPage: Page = page === 'result' ? 'setup' : page === 'players' || page === 'formats' || page === 'pairs' || page === 'history' ? 'more' : page;
    const watching = viewerPage === 'watch' || viewerPage === 'live' || viewerPage === 'matches';
    const viewerTitle = watching ? (store.settings.watch?.title ?? PAGE_TITLES.watch) : viewerPage === 'home' ? 'ホーム' : PAGE_TITLES[viewerPage];
    const viewerBack = viewerPage === 'settings' ? BACK_TARGETS.settings : undefined;
    return (
      <div className="app viewer-shell">
        <header className="app-header">
          {viewerBack ? (
            <button type="button" className="btn icon ghost header-back" onClick={() => setPage(viewerBack)} aria-label="戻る">
              <Icon name="chevronLeft" size={24} />
            </button>
          ) : (
            <span className="brand-mark" aria-hidden="true">
              <Icon name="target" size={20} />
            </span>
          )}
          <span className="header-titles">
            <span className="kicker">LEAGUE ORDER</span>
            <h1>{viewerTitle}</h1>
          </span>
          <button type="button" className="btn small" onClick={register}>
            チームを登録
          </button>
        </header>
        <main className={['app-main', watching || viewerPage === 'analytics' || viewerPage === 'home' ? 'wide' : ''].filter(Boolean).join(' ')}>
          {applyUpdate ? (
            <div className="notice info">
              <Icon name="refresh" size={18} />
              <span className="grow small-text">新しいバージョンがあります。</span>
              <button type="button" className="btn small primary" onClick={applyUpdate}>
                更新
              </button>
            </div>
          ) : null}
          <div className="page-view" key={viewerPage}>
            {viewerPage === 'home' ? <ViewerHome onRegister={register} onNavigate={setPage} /> : null}
            {watching ? (
              <Suspense fallback={<p className="small-text muted">読み込み中…</p>}>
                <MatchesEntry key={viewerPage} page={viewerPage as 'watch' | 'live' | 'matches'} onNavigate={setPage} />
              </Suspense>
            ) : null}
            {viewerPage === 'analytics' ? (
              <Suspense fallback={<p className="small-text muted">読み込み中…</p>}>
                <AnalyticsEntry onNavigate={setPage} />
              </Suspense>
            ) : null}
            {viewerPage === 'setup' ? <ViewerOrder onRegister={register} onNavigate={setPage} /> : null}
            {viewerPage === 'more' ? <MorePage onNavigate={setPage} onShowChangelog={() => setShowChangelog(true)} onRegister={register} /> : null}
            {viewerPage === 'settings' ? <SettingsPage /> : null}
          </div>
        </main>
        <TabBar active={TAB_FOR_PAGE[viewerPage] ?? viewerPage} onSelect={setPage} />
        {showChangelog ? <ChangelogSheet onClose={() => setShowChangelog(false)} /> : null}
      </div>
    );
  }

  if (!hasTeams) {
    return (
      <WelcomePage
        onWatchBack={store.settings.watch ? () => setRegistering(false) : undefined}
        onCreated={(next) => {
          if (next.kind === 'editFormat') {
            setFormatToEdit(next.formatId);
            setPage('formats');
          } else {
            setPage('home');
          }
        }}
      />
    );
  }

  const latest = latestVersion(record?.versions ?? []);
  const working: WorkingOrderSummary | null = solution
    ? { lifecycle, version: latest?.version ?? 0, label: solution.meta.label, saved: !unsaved }
    : null;

  const hasActionBar =
    page === 'setup' || page === 'result' || page === 'players' || page === 'formats';
  const wide = page === 'home' || page === 'setup' || page === 'result' || page === 'analytics' || page === 'matches' || page === 'live' || page === 'watch';
  const backTarget = BACK_TARGETS[page];
  const activeTab = TAB_FOR_PAGE[page] ?? page;
  const teamName = store.activeTeam?.name ?? 'チーム未設定';
  const title = page === 'home' ? (store.activeTeam?.name ?? PAGE_TITLES.home) : PAGE_TITLES[page];
  const stateMeta = STATE_META[lifecycle];

  return (
    <div className="app">
      <header className="app-header">
        {backTarget ? (
          <button
            type="button"
            className="btn icon ghost header-back"
            onClick={() => setPage(backTarget)}
            aria-label="戻る"
          >
            <Icon name="chevronLeft" size={24} />
          </button>
        ) : (
          <span className="brand-mark" aria-hidden="true">
            <Icon name="target" size={20} />
          </span>
        )}
        <span className="header-titles">
          <span className="kicker">
            LEAGUE ORDER
            {page !== 'home' ? <span className="team"> / {teamName}</span> : null}
          </span>
          {/* Keyed by the title, so every screen change replays the kinetic entrance. */}
          <h1 key={title}>
            <KineticText text={title} step={22} />
          </h1>
        </span>
        {page === 'result' && solution ? (
          <StatusBadge tone={stateMeta.tone} icon={stateMeta.icon}>
            {lifecycle === 'DRAFT' ? 'DRAFT' : `v${latest?.version ?? 1}`}
          </StatusBadge>
        ) : null}
        {page === 'home' && store.activeTeam?.demo ? <span className="demo-badge">DEMO</span> : null}
        <MenuButton open={menuOpen} onClick={() => setMenuOpen(true)} />
      </header>

      <main
        className={['app-main', wide ? 'wide' : '', hasActionBar ? 'has-action-bar' : '']
          .filter(Boolean)
          .join(' ')}
      >
        <Breadcrumbs page={page} onNavigate={setPage} />
        {applyUpdate ? (
          <div className="notice info">
            <Icon name="refresh" size={18} />
            <span className="grow small-text">新しいバージョンがあります。</span>
            <button type="button" className="btn small primary" onClick={applyUpdate}>
              更新
            </button>
          </div>
        ) : null}
        {/* Keyed by the screen: its sections enter in a short stagger (CSS, `.page-view`). */}
        <div className="page-view" key={page}>
        {page === 'home' ? (
          <HomePage
            onNavigate={setPage}
            onNewOrder={() => startNewOrder()}
            working={working}
            onResume={() => setPage('result')}
            onNextMatch={generateNextMatch}
            currentParticipants={draft?.participants ?? null}
            onOpenOrder={openSavedOrder}
          />
        ) : null}
        {page === 'players' ? <PlayersPage /> : null}
        {page === 'pairs' ? <PairsPage /> : null}
        {page === 'formats' ? <FormatsPage initialEditId={formatToEdit} /> : null}
        {page === 'setup' && draft ? (
          <SetupPage
            draft={draft}
            onDraftChange={setDraft}
            match={match}
            onMatchChange={setMatch}
            onGenerate={handleGenerate}
            generating={generating}
            editing={
              record
                ? { title: record.title, latestVersion: latest?.version ?? null }
                : null
            }
            // Detaching drops the working copy, so it asks first exactly like a new order.
            onDetach={() => startNewOrder()}
            onNavigate={setPage}
          />
        ) : null}
        {page === 'result' ? (
          session ? (
            <ResultPage
              session={session}
              dispatch={dispatch}
              games={games}
              diagnostics={diagnostics}
              diagnosticInput={diagnosticInput}
              generating={generating}
              match={match}
              onMatchChange={setMatch}
              onRegenerate={handleRegenerate}
              onReoptimise={handleReoptimise}
              record={record}
              lifecycle={lifecycle}
              seasonStatus={seasonStatus}
              onFinalize={handleFinalize}
              onSaveDraft={handleSaveDraft}
              onCommitSeason={handleCommitSeason}
              onWithdrawSeason={handleWithdrawSeason}
            />
          ) : (
            <EmptyState
              kicker="NO ORDER YET"
              title="まだオーダーがありません"
              action={
                <button type="button" className="btn primary" onClick={() => setPage('setup')}>
                  オーダーを作る
                </button>
              }
            >
              条件を設定して、最初のオーダーを生成してください。
            </EmptyState>
          )
        ) : null}
        {page === 'history' ? (
          <HistoryPage onOpen={openSavedOrder} onNewOrder={() => startNewOrder()} />
        ) : null}
        {page === 'settings' ? <SettingsPage /> : null}
        {page === 'more' ? <MorePage onNavigate={setPage} onShowChangelog={() => setShowChangelog(true)} /> : null}
        {page === 'analytics' ? (
          <Suspense fallback={<p className="small-text muted">読み込み中…</p>}>
            <AnalyticsEntry onNavigate={setPage} />
          </Suspense>
        ) : null}
        {page === 'matches' || page === 'live' || page === 'watch' ? (
          <Suspense fallback={<p className="small-text muted">読み込み中…</p>}>
            <MatchesEntry key={page} page={page} onNavigate={setPage} />
          </Suspense>
        ) : null}
        </div>
      </main>

      <TabBar
        active={activeTab}
        // Once an order has been generated, the ORDER tab returns to the result rather than the
        // setup form: that is the screen the captain is working on, and the header's back arrow
        // still leads to the setup.
        onSelect={(next) => setPage(next === 'setup' && session?.present.current ? 'result' : next)}
      />

      {menuOpen ? (
        <MenuDrawer
          page={page}
          teamName={teamName}
          leagueName={store.activeTeam?.leagueName}
          showAnalytics
          working={solution ? { lifecycle, version: latest?.version ?? 0 } : null}
          onNavigate={setPage}
          onNewOrder={() => startNewOrder()}
          onShowChangelog={() => setShowChangelog(true)}
          onClose={() => setMenuOpen(false)}
        />
      ) : null}

      {showChangelog ? <ChangelogSheet onClose={() => setShowChangelog(false)} /> : null}

      {confirmDiscard ? (
        <ConfirmDialog
          title="新しいオーダーを作る"
          message="作業中のオーダーに保存されていない変更があります。破棄して新しいオーダーを作りますか？ 残す場合は結果画面で保存または確定してください。"
          confirmLabel="破棄して作成"
          destructive
          onCancel={() => setConfirmDiscard(null)}
          onConfirm={() => {
            const action = confirmDiscard;
            setConfirmDiscard(null);
            action();
          }}
        />
      ) : null}
    </div>
  );
}

/** Same header as far as a shared order is concerned (the fields `orderFingerprint` reads). */
function sameMatch(a: MatchInfo, b: MatchInfo): boolean {
  return (
    a.leagueName.trim() === b.leagueName.trim() &&
    a.teamName.trim() === b.teamName.trim() &&
    a.opponentName.trim() === b.opponentName.trim() &&
    a.matchDate.trim() === b.matchDate.trim()
  );
}

/** The draft without its one-order helpers (and their participant rows). */
function clearGuests(draft: SetupDraft): SetupDraft {
  const gone = new Set(draft.guests.map((guest) => guest.id));
  return { ...draft, guests: [], participants: draft.participants.filter((config) => !gone.has(config.playerId)) };
}

/** The bottom bar: the same five tabs with or without a team. */
function TabBar({ active, onSelect }: { active: Page; onSelect: (page: Page) => void }): React.JSX.Element {
  return (
    <nav className="tab-bar" aria-label="メインナビゲーション">
      {TABS.map((tab) => (
        <button type="button" key={tab.page} onClick={() => onSelect(tab.page)} aria-current={active === tab.page ? 'page' : undefined}>
          <span className="tab-icon" aria-hidden="true">
            <Icon name={tab.icon} size={21} />
          </span>
          <span className="tab-label">{tab.label}</span>
        </button>
      ))}
    </nav>
  );
}
